<?php
session_start(); require 'config.php'; require 'functions.php'; verify_csrf(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(isset($_POST['delete_id'])){$pdo->prepare("DELETE FROM matches WHERE match_id=?")->execute([int_post('delete_id')]);flash('Match deleted.');redirect('matches.php');}
  if(isset($_POST['save_match'])){$id=int_post('match_id');$tid=int_post('tournament_id');$a=int_post('team_a_id');$b=int_post('team_b_id');$date=trim((string)post('scheduled_at'));$status=trim((string)post('status'));if(!$tid||!$a||!$b||$a===$b)throw new RuntimeException('Choose a tournament and two different teams.');$check=$pdo->prepare("SELECT COUNT(*) FROM tournament_registrations WHERE tournament_id=? AND team_id IN (?,?)");$check->execute([$tid,$a,$b]);if((int)$check->fetchColumn()!==2)throw new RuntimeException('Both teams must be registered in the selected tournament.');if($id){$st=$pdo->prepare("UPDATE matches SET tournament_id=?,team_a_id=?,team_b_id=?,scheduled_at=?,status=? WHERE match_id=?");$st->execute([$tid,$a,$b,$date?:null,$status,$id]);flash('Match updated.');}else{$st=$pdo->prepare("INSERT INTO matches(tournament_id,team_a_id,team_b_id,scheduled_at,status) VALUES(?,?,?,?,?)");$st->execute([$tid,$a,$b,$date?:null,$status]);flash('Match scheduled.');}redirect('matches.php');}
  if(isset($_POST['save_result'])){$mid=int_post('match_id');$sa=int_post('score_a');$sb=int_post('score_b');if($sa<0||$sb<0)throw new RuntimeException('Scores cannot be negative.');$st=$pdo->prepare("SELECT team_a_id,team_b_id FROM matches WHERE match_id=?");$st->execute([$mid]);$m=$st->fetch();if(!$m)throw new RuntimeException('Match not found.');$winner=$sa===$sb?null:($sa>$sb?(int)$m['team_a_id']:(int)$m['team_b_id']);$st=$pdo->prepare("INSERT INTO results(match_id,team_a_id,team_b_id,score_a,score_b,winner_team_id) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE score_a=VALUES(score_a),score_b=VALUES(score_b),winner_team_id=VALUES(winner_team_id),played_at=CURRENT_TIMESTAMP");$st->execute([$mid,$m['team_a_id'],$m['team_b_id'],$sa,$sb,$winner]);$pdo->prepare("UPDATE matches SET status='completed' WHERE match_id=?")->execute([$mid]);flash('Result saved. Leaderboard updated.');redirect('matches.php');}
 }catch(Throwable $e){$error=$e instanceof PDOException&&$e->getCode()==='23000'?'Unable to save due to a database relationship constraint.':$e->getMessage();}
}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM matches WHERE match_id=?");$st->execute([(int)$_GET['edit']]);$edit=$st->fetch()?:null;}
$tournaments=$pdo->query("SELECT tournament_id,name FROM tournaments ORDER BY name")->fetchAll();
$regs=$pdo->query("SELECT tr.tournament_id,t.team_id,t.name FROM tournament_registrations tr JOIN teams t ON t.team_id=tr.team_id ORDER BY t.name")->fetchAll();
$matches=$pdo->query("SELECT m.*,t.name tournament,ta.name team_a,tb.name team_b,r.score_a,r.score_b,r.winner_team_id,tw.name winner FROM matches m JOIN tournaments t ON t.tournament_id=m.tournament_id JOIN teams ta ON ta.team_id=m.team_a_id JOIN teams tb ON tb.team_id=m.team_b_id LEFT JOIN results r ON r.match_id=m.match_id LEFT JOIN teams tw ON tw.team_id=r.winner_team_id ORDER BY m.scheduled_at DESC,m.match_id DESC")->fetchAll();
page_header('Matches & Results','matches');
?>
<div class="page-heading"><div><h1>Matches & Results</h1><p>Schedule matchups, record scores, and update standings.</p></div><span class="tag"><?= count($matches) ?> matches</span></div>
<?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<div class="row g-4"><div class="col-xl-4"><div class="cardx"><div class="section-title"><?= $edit?'Edit match':'Schedule a match' ?></div><?php if(!$tournaments): ?><div class="small-note">Create a tournament first, then register at least two teams for it.</div><?php else: ?><form method="post"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= e($edit['match_id']??'') ?>"><div class="mb-3"><label class="form-label">Tournament</label><select class="form-select" name="tournament_id" id="tournamentSelect" required><?php foreach($tournaments as $t): ?><option value="<?= (int)$t['tournament_id'] ?>" <?= (int)($edit['tournament_id']??0)===(int)$t['tournament_id']?'selected':'' ?>><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Team A</label><select class="form-select" name="team_a_id" id="teamA" required></select></div><div class="mb-3"><label class="form-label">Team B</label><select class="form-select" name="team_b_id" id="teamB" required></select></div><div class="mb-3"><label class="form-label">Scheduled date & time</label><input class="form-control" type="datetime-local" name="scheduled_at" value="<?= e(isset($edit['scheduled_at'])&&$edit['scheduled_at']?date('Y-m-d\TH:i',strtotime($edit['scheduled_at'])):'') ?>"></div><div class="mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['scheduled','live','completed'] as $s): ?><option value="<?= $s ?>" <?= ($edit['status']??'scheduled')===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary w-100" name="save_match" value="1"><?= $edit?'Save changes':'Schedule match' ?></button><?php if($edit): ?><a href="matches.php" class="btn btn-outline-light w-100 mt-2">Cancel</a><?php endif; ?></form><?php endif; ?></div><div class="small-note mt-3"><i class="bi bi-lightbulb me-1"></i>Both teams must be registered in that tournament before scheduling.</div></div>
<div class="col-xl-8"><div class="cardx"><div class="section-title">Match center</div><?php if(!$matches): ?><div class="empty-state"><i class="bi bi-controller"></i>No matches scheduled yet.</div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Matchup</th><th>Tournament / Date</th><th>Score</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($matches as $m): ?><tr><td><div class="fw-semibold"><?= e($m['team_a']) ?></div><div class="small muted">vs <?= e($m['team_b']) ?></div><?php if($m['winner']): ?><div class="small" style="color:#86efac">Winner: <?= e($m['winner']) ?></div><?php elseif($m['score_a']!==null): ?><div class="small muted">Draw</div><?php endif; ?></td><td><div><?= e($m['tournament']) ?></div><div class="small muted"><?= $m['scheduled_at']?e(date('M j, Y H:i',strtotime($m['scheduled_at']))):'Date TBD' ?></div></td><td><?php if($m['score_a']!==null): ?><span class="score"><?= (int)$m['score_a'] ?> : <?= (int)$m['score_b'] ?></span><?php else: ?><span class="muted">— : —</span><?php endif; ?></td><td><span class="tag <?= $m['status']==='completed'?'tag-green':($m['status']==='live'?'tag-yellow':'') ?>"><?= e(ucfirst($m['status'])) ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-light mb-1" href="matches.php?edit=<?= (int)$m['match_id'] ?>"><i class="bi bi-pencil"></i></a><?= delete_button('matches.php',(int)$m['match_id']) ?><form method="post" class="mt-2 d-flex align-items-center gap-1"><?= csrf_field() ?><input type="hidden" name="match_id" value="<?= (int)$m['match_id'] ?>"><input class="form-control form-control-sm" style="width:48px;padding:5px" type="number" min="0" name="score_a" value="<?= e($m['score_a']??0) ?>" aria-label="Team A score" required><span class="muted">:</span><input class="form-control form-control-sm" style="width:48px;padding:5px" type="number" min="0" name="score_b" value="<?= e($m['score_b']??0) ?>" aria-label="Team B score" required><button class="btn btn-sm btn-primary" name="save_result" value="1" title="Save result"><i class="bi bi-check2"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></div>
<script>
const rosterData = <?= json_encode(array_map(fn($r)=>['tournament_id'=>(int)$r['tournament_id'],'team_id'=>(int)$r['team_id'],'name'=>$r['name']],$regs), JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
const selectedA = <?= (int)($edit['team_a_id']??0) ?>, selectedB = <?= (int)($edit['team_b_id']??0) ?>;
function fillTeams(){const tid=Number(document.getElementById('tournamentSelect')?.value||0);[['teamA',selectedA],['teamB',selectedB]].forEach(([id,selected])=>{const el=document.getElementById(id);if(!el)return;const previous=Number(el.value||selected);el.innerHTML='<option value="">Select team</option>';rosterData.filter(r=>r.tournament_id===tid).forEach(r=>{const o=document.createElement('option');o.value=r.team_id;o.textContent=r.name;if(r.team_id===previous)o.selected=true;el.appendChild(o);});});}
document.getElementById('tournamentSelect')?.addEventListener('change',fillTeams);fillTeams();
</script>
<?php page_footer(); ?>
